INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'en', 'The Basilica of the Annunciation is a Catholic church in Nazareth, Israel. It is one of the largest churches in the Middle East and marks the traditional site where the Archangel Gabriel announced to Mary that she would bear Jesus.', 'The current basilica was built in 1969, designed by Italian architect Giovanni Muzio. It stands over the ruins of earlier Byzantine and Crusader churches. The site has been a place of Christian pilgrimage since ancient times.', 'The church serves the local Catholic community in Nazareth and welcomes pilgrims from around the world. Regular masses are held in multiple languages.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'en', 'The Church of the Nativity in Bethlehem stands over the grotto that Christian tradition has honoured since the 2nd century as the birthplace of Jesus. It is one of the oldest continuously used churches in the world and a UNESCO World Heritage Site.', 'The first basilica was commissioned by Emperor Constantine and his mother Helena around 327 AD. After it was damaged in the 6th century, Emperor Justinian rebuilt it on a larger scale, and much of today''s church dates from that rebuilding. Crusader-era mosaics and painted columns still survive inside.', 'The church is shared by the Greek Orthodox, Roman Catholic (Franciscan) and Armenian Apostolic communities under the historic Status Quo arrangement. Local Christian families of Bethlehem worship here alongside pilgrims from around the world, especially at Christmas.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'en', 'The Church of the Holy Sepulchre in the Old City of Jerusalem contains the two holiest sites of Christianity: Golgotha, where Jesus was crucified, and the tomb where he was buried and rose again, according to tradition.', 'Emperor Constantine built the first church here in the 4th century; it was dedicated in 335 AD. It was destroyed in 1009 and rebuilt in the 11th century, and the Crusaders gave it much of its present form in the 12th century. The Edicule over the tomb was restored in 2016–2017.', 'Care of the church is shared by the Greek Orthodox, Roman Catholic (Franciscan) and Armenian Apostolic churches, with the Coptic, Ethiopian and Syriac Orthodox communities also holding chapels, under the Status Quo of 1852. Its doors are opened each morning by Muslim families who have kept the keys for centuries.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ar', 'كنيسة البشارة هي كنيسة كاثوليكية تقع في الناصرة، إسرائيل. وهي واحدة من أكبر الكنائس في الشرق الأوسط وتحتفل بالموقع التقليدي حيث بشّر الملاك جبرائيل مريم بأنها ستلد يسوع.', 'تم بناء البازيليكا الحالية عام 1969، صممها المهندس المعماري الإيطالي جيوفاني موتسيو. تقف على أنقاض كنائس بيزنطية وصليبية سابقة. كان الموقع مكانًا للحج المسيحي منذ العصور القديمة.', 'تخدم الكنيسة المجتمع الكاثوليكي المحلي في الناصرة وترحب بالحجاج من جميع أنحاء العالم. تقام القداس بانتظام بلغات متعددة.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ar', 'تقوم كنيسة المهد في بيت لحم فوق المغارة التي يُكرّمها التقليد المسيحي منذ القرن الثاني باعتبارها مكان ولادة يسوع المسيح. وهي واحدة من أقدم الكنائس التي لا تزال قيد الاستخدام المستمر في العالم، وموقع مدرج على لائحة التراث العالمي لليونسكو.', 'أمر الإمبراطور قسطنطين ووالدته هيلانة ببناء البازيليكا الأولى حوالي عام 327 م. وبعد أن تضررت في القرن السادس، أعاد الإمبراطور جستنيان بناءها على نطاق أوسع، ويعود جزء كبير من الكنيسة الحالية إلى ذلك البناء. لا تزال الفسيفساء والأعمدة المرسومة من العصر الصليبي باقية في الداخل.', 'تشترك في الكنيسة طوائف الروم الأرثوذكس والكاثوليك (الفرنسيسكان) والأرمن الأرثوذكس بموجب ترتيب الوضع الراهن التاريخي. تصلي فيها عائلات بيت لحم المسيحية المحلية جنبًا إلى جنب مع الحجاج القادمين من جميع أنحاء العالم، خاصة في عيد الميلاد.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ar', 'تضم كنيسة القيامة في البلدة القديمة بالقدس أقدس موقعين في المسيحية: الجلجثة، حيث صُلب يسوع، والقبر الذي دُفن فيه وقام منه، بحسب التقليد.', 'بنى الإمبراطور قسطنطين الكنيسة الأولى هنا في القرن الرابع، وكُرِّست عام 335 م. دُمِّرت عام 1009 وأُعيد بناؤها في القرن الحادي عشر، ومنحها الصليبيون معظم شكلها الحالي في القرن الثاني عشر. رُمِّم الإيديكول (الكنيسة الصغيرة) فوق القبر بين عامي 2016 و2017.', 'تتشارك في رعاية الكنيسة طوائف الروم الأرثوذكس والكاثوليك (الفرنسيسكان) والأرمن الأرثوذكس، كما تحتفظ الطوائف القبطية والإثيوبية والسريانية الأرثوذكسية بمصليات فيها، وذلك بموجب الوضع الراهن لعام 1852. تُفتح أبوابها كل صباح على يد عائلات مسلمة تحافظ على مفاتيحها منذ قرون.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
