INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ar', 'مبادرة شاملة لتصوير ومسح وتوثيق مواقع التراث المسيحي والقطع الأثرية والمخطوطات في جميع أنحاء إسرائيل والمناطق المحيطة بها. سيحافظ هذا الأرشيف الرقمي على سجلات تاريخية لا تقدَّر بثمن للباحثين وللأجيال القادمة.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
