INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'el', 'Αναστήλωση', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'el', 'Αυτό το έργο επικεντρώνεται στις κρίσιμες ανάγκες αναστήλωσης της βασιλικής, συμπεριλαμβανομένων δομικών επισκευών, καθαρισμού της πρόσοψης και διατήρησης των αρχικών αρχιτεκτονικών στοιχείων. Οι εργασίες θα διασφαλίσουν ότι το κτίριο παραμένει ασφαλές και προσβάσιμο για τις μελλοντικές γενιές.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'el', 'Αναστήλωση του κεντρικού κλίτους και της πρόσοψης της Βασιλικής του Ευαγγελισμού.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'el', 'Αναστήλωση της Βασιλικής – Φάση 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'el', 'Τεκμηρίωση', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'el', 'Μια ολοκληρωμένη πρωτοβουλία για τη φωτογράφηση, σάρωση και τεκμηρίωση χριστιανικών τόπων κληρονομιάς, τεχνέργων και χειρογράφων σε ολόκληρο το Ισραήλ και τις γύρω περιοχές. Αυτό το ψηφιακό αρχείο θα διαφυλάξει ανεκτίμητα ιστορικά τεκμήρια για ερευνητές και μελλοντικές γενιές.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'el', 'Ψηφιακή τεκμηρίωση χριστιανικών τόπων κληρονομιάς σε ολόκληρη την Αγία Γη.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'el', 'Τεκμηρίωση της κληρονομιάς της Αγίας Γης', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'es', 'La Basílica de la Anunciación es una iglesia católica en Nazaret, Israel. Es una de las iglesias más grandes de Oriente Medio y señala el lugar tradicional donde el arcángel Gabriel anunció a María que ella daría a luz a Jesús.', 'La basílica actual fue construida en 1969, diseñada por el arquitecto italiano Giovanni Muzio. Se alza sobre las ruinas de iglesias bizantinas y cruzadas anteriores. El lugar ha sido un sitio de peregrinación cristiana desde la antigüedad.', 'La iglesia atiende a la comunidad católica local de Nazaret y da la bienvenida a peregrinos de todo el mundo. Se celebran misas con regularidad en varios idiomas.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'es', 'La Basílica de la Natividad, en Belén, se alza sobre la gruta que la tradición cristiana venera desde el siglo II como el lugar de nacimiento de Jesús. Es una de las iglesias en uso continuo más antiguas del mundo y Patrimonio de la Humanidad por la UNESCO.', 'La primera basílica fue encargada por el emperador Constantino y su madre Elena hacia el año 327 d. C. Tras sufrir daños en el siglo VI, el emperador Justiniano la reconstruyó a mayor escala, y gran parte de la iglesia actual data de esa reconstrucción. En su interior aún se conservan mosaicos y columnas pintadas de la época de las Cruzadas.', 'La iglesia es compartida por las comunidades griega ortodoxa, católica romana (franciscana) y apostólica armenia bajo el histórico acuerdo del Statu quo. Las familias cristianas locales de Belén oran aquí junto a peregrinos de todo el mundo, especialmente en Navidad.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'es', 'La Iglesia del Santo Sepulcro, en el Casco Antiguo de Jerusalén, contiene los dos lugares más sagrados del cristianismo: el Gólgota, donde Jesús fue crucificado, y el sepulcro donde, según la tradición, fue enterrado y resucitó.', 'El emperador Constantino construyó aquí la primera iglesia en el siglo IV; fue consagrada en el año 335 d. C. Fue destruida en 1009 y reconstruida en el siglo XI, y los cruzados le dieron gran parte de su forma actual en el siglo XII. El Edículo sobre el sepulcro fue restaurado entre 2016 y 2017.', 'El cuidado de la iglesia es compartido por las iglesias griega ortodoxa, católica romana (franciscana) y apostólica armenia, mientras que las comunidades copta, etíope y siríaca ortodoxa también tienen capillas propias, conforme al Statu quo de 1852. Sus puertas son abiertas cada mañana por familias musulmanas que han custodiado las llaves durante siglos.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
