INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ro', 'Acest proiect se concentrează pe nevoile critice de restaurare ale bazilicii, incluzând reparații structurale, curățarea fațadei și conservarea elementelor arhitecturale originale. Lucrările vor asigura că edificiul rămâne sigur și accesibil pentru generațiile viitoare.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
