INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ro', 'O inițiativă amplă de fotografiere, scanare și documentare a siturilor, artefactelor și manuscriselor de patrimoniu creștin din Israel și din regiunile învecinate. Această arhivă digitală va păstra înregistrări istorice neprețuite pentru cercetători și generațiile viitoare.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
