INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ru', 'Проект направлен на решение неотложных реставрационных задач базилики, включая ремонт конструкций, очистку фасада и сохранение подлинных архитектурных элементов. Работы обеспечат безопасность и доступность здания для будущих поколений.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
