INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ru', 'Масштабная инициатива по фотографированию, сканированию и документированию объектов христианского наследия, артефактов и рукописей в Израиле и соседних регионах. Этот цифровой архив сохранит бесценные исторические свидетельства для исследователей и будущих поколений.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ru', 'Цифровое документирование объектов христианского наследия по всей Святой земле.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'ru', 'Документирование наследия Святой земли', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'uk', 'Базиліка Благовіщення — католицький храм у Назареті (Ізраїль). Це одна з найбільших церков на Близькому Сході. Вона стоїть на місці, де, за переданням, Архангел Гавриїл сповістив Діві Марії, що вона народить Ісуса.', 'Нинішню базиліку збудовано 1969 року за проєктом італійського архітектора Джованні Муціо. Вона височіє над руїнами давніших церков візантійської доби та часів хрестових походів. Від давніх часів це місце приваблює християнських паломників.', 'Храм служить місцевій католицькій громаді Назарета й приймає паломників з усього світу. Меси регулярно відправляють кількома мовами.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'uk', 'Храм Різдва Христового у Вифлеємі стоїть над печерою, яку християнське передання з II століття шанує як місце народження Ісуса. Це один із найдавніших храмів світу, у якому богослужіння звершуються безперервно, і об’єкт Світової спадщини ЮНЕСКО.', 'Першу базиліку спорудили близько 327 року н. е. з волі імператора Костянтина та його матері Олени. Після пошкоджень у VI столітті імператор Юстиніан відбудував її в більшому масштабі, і значна частина нинішнього храму походить саме з тієї відбудови. Усередині досі збереглися мозаїки та розписані колони доби хрестоносців.', 'Храм перебуває в спільному віданні трьох громад — грецької православної, римо-католицької (францисканці) та вірменської апостольської — відповідно до історичного статус-кво. Місцеві християнські родини Вифлеєма моляться тут разом із паломниками з усього світу, особливо на Різдво.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'uk', 'Храм Гробу Господнього в Старому місті Єрусалима об’єднує дві найбільші святині християнства: Голгофу, де було розіп’ято Ісуса, і Гріб Господній — місце, де, за переданням, Він був похований і воскрес.', 'Перший храм тут збудував імператор Костянтин у IV столітті; його освятили 335 року н. е. У 1009 році храм зруйнували, в XI столітті відбудували, а в XII столітті хрестоносці значною мірою надали йому нинішнього вигляду. Кувуклію над Гробом Господнім відреставрували в 2016–2017 роках.', 'Храм перебуває в спільному віданні трьох церков — Грецької православної, Римо-католицької (францисканці) та Вірменської апостольської; власні каплиці мають також православні громади коптів, ефіопів і сирійців. Цей устрій закріплено статус-кво 1852 року. Щоранку двері храму відчиняють мусульманські родини, які століттями зберігають його ключі.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
